const input = $input.first().json;
const body = (typeof input.body === 'object' && input.body !== null) ? input.body : input;
const errors = [];
const required = ['application_id', 'dealer_id', 'dealer_name', 'full_name', 'email'];
for (const f of required) if (!body[f]) errors.push(f);

if (errors.length) {
  return [{ json: { ok: false, errors, body } }];
}

const hasPassword = Boolean(body.temporary_password);
return [{
  json: {
    ok: true,
    application_id:    body.application_id,
    dealer_id:         body.dealer_id,
    dealer_name:       body.dealer_name,
    full_name:         body.full_name,
    email:             body.email,
    temporary_password: body.temporary_password || null,
    has_password:      hasPassword,
    login_url:         body.login_url         || 'https://blacklabelmarket.es/login',
    dashboard_url:     body.dashboard_url     || 'https://blacklabelmarket.es/dashboard',
    approved_at:       body.approved_at       || new Date().toISOString()
  }
}];

const d = $input.first().json;
const MARKET_URL = process.env.MARKET_URL || 'https://blacklabelmarket.es';

const accessInfo = d.has_password
  ? `Tus credenciales de acceso son:
- Email: ${d.email}
- Contraseña temporal: ${d.temporary_password}

Deberás cambiar la contraseña en tu primer acceso.`
  : `Accede con el email ${d.email}. Si no recuerdas tu contraseña, usa la opción de recuperación en ${d.login_url || MARKET_URL + '/recuperar'}.`;

const briefing = `Eres redactor senior de Black Label Market. Escribe un email de bienvenida en español para un concesionario que acaba de ser aprobado en la plataforma.

Contexto del concesionario:
- Nombre showroom: ${d.dealer_name}
- Nombre de contacto: ${d.full_name}

El email debe:
1. Felicitarles por la aprobación de forma cálida pero profesional
2. Explicar en 3 pasos concretos cómo empezar: (a) completar perfil, (b) subir primeros vehículos, (c) activar notificaciones de leads
3. Incluir los datos de acceso tal cual aparecen aquí: ${accessInfo}
4. URL de acceso: ${d.login_url || MARKET_URL + '/login'}
5. URL del panel: ${d.dashboard_url || MARKET_URL + '/dashboard'}
6. Mencionar que el equipo está disponible para cualquier duda
7. Firma: «El equipo de Black Label Market»

Tono: premium, conciso, acogedor. Sin párrafos largos. Sin palabras vacías. Devuelve SOLO el HTML del cuerpo del email (sin <html>/<head>/<body> exterior, con <p> y <strong> para estructura).`;

return [{
  json: {
    ...d,
    claudeRequest: {
      model: process.env.ANTHROPIC_MODEL || 'claude-haiku-4-5-20251001',
      max_tokens: 1200,
      messages: [{ role: 'user', content: briefing }]
    }
  }
}];

const d = $('Preparar prompt email bienvenida').first().json;
const claude = $input.first().json;

let body = '';
if (Array.isArray(claude.content)) {
  body = claude.content.map(b => b.text || '').join('\n').trim();
} else if (claude.text) {
  body = claude.text;
} else {
  body = `<p>Hola ${d.full_name},</p><p>Tu showroom <strong>${d.dealer_name}</strong> ha sido aprobado en Black Label Market.</p><p>Ya puedes acceder a tu panel en: <a href="${d.login_url}">${d.login_url}</a></p><p>El equipo de Black Label Market</p>`;
}

const MAIL_FROM = process.env.MAIL_FROM || 'Black Label Market <no-reply@blacklabelmarket.es>';
const ADMIN_EMAIL = process.env.ADMIN_EMAIL || 'aldeiaceo@gmail.com';

return [{
  json: {
    ...d,
    emailPayload: {
      from: MAIL_FROM,
      to: [d.email],
      subject: `Bienvenido a Black Label Market — ${d.dealer_name}`,
      html: body
    },
    slackText: `*✅ Nuevo showroom aprobado*\n\n*Showroom:* ${d.dealer_name}\n*Contacto:* ${d.full_name} (${d.email})\n*Dealer ID:* ${d.dealer_id}\n*Email bienvenida:* enviado`,
    internalEmailPayload: {
      from: MAIL_FROM,
      to: [ADMIN_EMAIL],
      subject: `Dealer aprobado: ${d.dealer_name}`,
      html: `<h2>Nuevo dealer aprobado</h2><p><strong>${d.dealer_name}</strong> (${d.email}) ha sido aprobado. Dealer ID: ${d.dealer_id}</p>`
    }
  }
}];
